import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r}from"./chunks/M-S-HDS-WF-Scr.ATovYKe5.js";import{_ as o,o as s,c as t,a3 as a}from"./chunks/framework.g9mfNVRQ.js";const h=JSON.parse('{"title":"Abonné Web Libre","description":"","frontmatter":{"source_hash":"8c757f2bd2","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/troubleshoot/webfollow.md","filePath":"fr/troubleshoot/webfollow.md"}'),n={name:"fr/troubleshoot/webfollow.md"};function l(p,e,u,d,c,f){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="libre-web-follower" tabindex="-1">Libre Web Follower <a class="header-anchor" href="#libre-web-follower" aria-label="Permalink to &quot;Libre Web Follower {#libre-web-follower}&quot;">​</a></h1><h2 id="system-setup" tabindex="-1">Configuration du système <a class="header-anchor" href="#system-setup" aria-label="Permalink to &quot;Configuration du système {#system-setup}&quot;">​</a></h2><p>Avec cette source de données, vous devez vous assurer que votre système est correctement configuré avec les applications du fabricant.</p><p><strong>L&#39;application principale (connectée au capteur Libre) doit envoyer les données vers le <a href="https://www.libreview.com/" target="_blank" rel="noreferrer">serveur</a> du fabricant.</strong></p><p>Déconnectez-vous puis reconnectez-vous au serveur pour vérifier que vous utilisez les bons identifiants.</p><p>Vérifiez que le serveur contient bien des données.</p><p><strong>L&#39;application <a href="https://play.google.com/store/search?q=librelinkup&amp;c=apps" target="_blank" rel="noreferrer">abonné</a> du fabricant doit recevoir les données partagées.</strong></p><p>Essayez de supprimer puis de renvoyer une invitation vers l&#39;application abonné du fabricant (depuis l&#39;application principale du fabricant).</p><p>Essayez de désinstaller puis de réinstaller l&#39;application abonné du fabricant.</p><ul><li>Utilisez de préférence les identifiants de l&#39;invitation pour vous connecter.</li><li>Si cela ne fonctionne pas, utilisez les identifiants de l&#39;application principale (serveur) et renvoyez l&#39;invitation.</li></ul><br><h2 id="xdrip-setup" tabindex="-1">Configuration de xDrip <a class="header-anchor" href="#xdrip-setup" aria-label="Permalink to &quot;Configuration de xDrip {#xdrip-setup}&quot;">​</a></h2><p>Une fois que le système fonctionne avec les applications du fabricant, vous pouvez dépanner xDrip.</p><ol><li>Vérifiez que la source de données est <a href="./../install/webfollower.html">Web follower</a>.</li><li>Utilisez les identifiants de l&#39;abonné que vous avez invité depuis l&#39;application principale du fabricant.</li><li>Si cela ne fonctionne pas, vous pouvez essayer les identifiants du serveur pour le dépannage, mais soyez prudent afin de limiter le risque de blocage du compte.</li></ol><br><h2 id="vendor-servers-updates" tabindex="-1">Mises à jour des serveurs du fabricant <a class="header-anchor" href="#vendor-servers-updates" aria-label="Permalink to &quot;Mises à jour des serveurs du fabricant {#vendor-servers-updates}&quot;">​</a></h2><p>Les mises à jour du serveur peuvent casser le mécanisme.</p><p><strong>Une fois xDrip corrigé</strong>, il peut être nécessaire de le réinitialiser en suivant cette séquence :</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   Web Follower</p></div><p>Modifiez le <code>Configuration script</code></p><div class="admonition xdripitem"><p class="admonition-title">Configuration Script</p><p> This is the community helper address or keyword</p></div><p>Ajoutez une espace après <code>beonlabs</code>, sélectionnez <code>Ok</code></p><img src="'+r+'" style="zoom:75%;"><p>Modifiez à nouveau le <code>Configuration script</code>, <strong>supprimez l&#39;espace</strong> après <code>beonlabs</code> et sélectionnez <code>Ok</code>.</p><p>Attendez jusqu&#39;à une minute que les données s&#39;affichent de nouveau.</p><br><p>Si le problème persiste, installez l&#39;application abonné du fabricant sur le même téléphone et vérifiez qu&#39;elle reçoit les données avec les mêmes identifiants.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Dernière modification le 8/12/2024</em></a></p>',29)])])}const _=o(n,[["render",l]]);export{h as __pageData,_ as default};
